inicial.estilo.css:
/* 1. body: o tema. Fundo #1b1e24, texto #f5f5f5, fonte Verdana, sans-serif e tudo centralizado */

/* 2. h1: cor #ffd23f e tamanho 40px */

/* 3. h2: cor hsl(145, 55%, 60%) */

/* 4. strong: cor tomato */

/* 5. img: fundo rgb(42, 46, 55) */

solucao.estilo.css:
/* Tema do cartão: tudo o que os filhos herdam fica no body */
body {
  background-color: #1b1e24;
  color: #f5f5f5;
  font-family: Verdana, sans-serif;
  text-align: center;
}

h1 {
  color: #ffd23f;
  font-size: 40px;
}

h2 {
  color: hsl(145, 55%, 60%);
}

strong {
  color: tomato;
}

img {
  background-color: rgb(42, 46, 55);
}

